35	/// Single-line submit: thin wrapper that pipes the line through
36	/// the batch path so there is exactly one place that mutates
37	/// state. Calling `make_submit` N times in a tight loop USED
38	/// to drop N-1 history entries because each call did
39	/// `(*deps.history).clone()` -> push one -> `set(new)` --
40	/// inside one event tick every clone read the same snapshot
41	/// and only the last `set` won (Tutorial Run-All bug, May 7
42	/// 2026). Routing through `make_submit_batch` collapses any
43	/// number of lines into a single read-modify-write.
44	pub fn make_submit(deps: EvalDeps) -> Callback<String> {
45	    let batch = make_submit_batch(deps);
46	    Callback::from(move |line: String| batch.emit(vec![line]))
47	}
48	
49	/// Evaluate every line in `lines` against the current session
50	/// in one pass, then commit all four state handles exactly
51	/// once. Empty/whitespace-only lines are skipped (matching
52	/// single-line submit semantics); `:clear` and `:help` are
53	/// honored mid-batch.
54	pub fn make_submit_batch(deps: EvalDeps) -> Callback<Vec<String>> {
55	    Callback::from(move |lines: Vec<String>| {
56	        let mut new_history = (*deps.history).clone();
57	        let mut new_cmds = (*deps.cmd_history).clone();
58	        let mut eval_queue: Vec<String> = Vec::new();
59	        for line in lines {
60	            let trimmed = line.trim();
61	            if trimmed.is_empty() {
62	                continue;
63	            }
64	            new_cmds.push(trimmed.to_string());
65	            if trimmed == ":clear" {
66	                deps.session.borrow().clear();
67	                new_history.clear();
68	                continue;
69	            }
70	            if let Some(name) = parse_upload_command(trimmed) {
71	                new_history.push(handle_upload_command(&deps, trimmed, &name));
72	                continue;
73	            }
74	            // Anything else hits the WASM evaluator, which may
75	            // block for seconds; defer to the spinner pipeline
76	            // (Saga 29 step 018) so the user sees a running
77	            // indicator instead of a frozen page.
78	            eval_queue.push(trimmed.to_string());
79	        }
80	        if new_cmds.is_empty() {
81	            return;
82	        }
83	        deps.cmd_history.set(new_cmds);
84	        deps.cmd_index.set(None);
85	        deps.input_value.set(String::new());
86	        if eval_queue.is_empty() {
87	            deps.history.set(new_history);
88	            return;
89	        }
90	        // Saga 29 step 018: push Running markers for each
91	        // queued line + paint, then process them one-at-a-time
92	        // through Timeout(0) yields so the spinner CSS keeps
93	        // animating during each eval.
94	        process_next_eval(deps.clone(), new_history, eval_queue, 0);
95	    })
96	}
