98	/// Saga 29 step 018: recursive Timeout-yielding eval loop for
99	/// REPL submissions. Pushes a Running marker, yields, evals,
100	/// replaces marker with result, recurses to next line.
101	fn process_next_eval(
102	    deps: EvalDeps,
103	    mut history: Vec<HistoryEntry>,
104	    queue: Vec<String>,
105	    idx: usize,
106	) {
107	    if idx >= queue.len() {
108	        deps.history.set(history);
109	        return;
110	    }
111	    let line = queue[idx].clone();
112	    push_running_marker(&mut history, &line);
113	    deps.history.set(history.clone());
114	    let deps_next = deps.clone();
115	    let queue_next = queue.clone();
116	    gloo::timers::callback::Timeout::new(0, move || {
117	        let entry = eval_one_line(&deps_next, &line);
118	        history.pop();
119	        history.push(entry);
120	        process_next_eval(deps_next, history, queue_next, idx + 1);
121	    })
122	    .forget();
123	}
