125	/// Saga 29 step 018: human-readable "this line is running"
126	/// caption tailored to the kind of line. Train blocks call out
127	/// the expected duration; everything else gets a generic
128	/// "evaluating..." marker that still tells the user the demo
129	/// hasn't hung. Saga 33 step 027: a "train 5"-shaped chunk
130	/// gets a chunk-sized caption so the user understands each
131	/// chunk is short and the page will recover between chunks;
132	/// large `train 30`+ blocks keep the long-duration warning.
133	pub(crate) fn running_message(line: &str) -> &'static str {
134	    let stripped = line.trim_start();
135	    if stripped.starts_with("train ") || stripped.starts_with("train{") {
136	        return train_caption(stripped);
137	    }
138	    if stripped.starts_with("repeat ") {
139	        "looping... (this can take a few seconds)"
140	    } else if stripped.contains("predict_batch")
141	        || stripped.contains("apply(")
142	        || stripped.contains("attention_weights")
143	    {
144	        "evaluating... (forward pass through the trained model)"
145	    } else if stripped.contains("svg(") {
146	        "rendering visualization..."
147	    } else {
148	        "evaluating..."
149	    }
150	}
