209	pub fn make_run_demo(
210	    session: Rc<RefCell<WasmSession>>,
211	    history: UseStateHandle<Vec<HistoryEntry>>,
212	) -> Callback<usize> {
213	    Callback::from(move |idx: usize| {
214	        let Some(demo) = DEMOS.get(idx) else {
215	            return;
216	        };
217	        session.borrow().clear();
218	        // Lead with a narration panel framing what the demo does
219	        // and why. Demo lines follow; the takeaway narration lands
220	        // after the final line in `schedule_demo_line`. Also bind
221	        // a `_demo` string in the session so `:describe _demo`
222	        // prints the intro + takeaway from the REPL.
223	        bind_demo_metadata(&session.borrow(), demo);
224	        let intro_entry = HistoryEntry {
225	            input: format!("About this demo -- {}", demo.name),
226	            output: demo.intro.to_string(),
227	            is_error: false,
228	            kind: EntryKind::Narration,
229	        };
230	        let entries = vec![intro_entry];
231	        history.set(entries.clone());
232	        // Evaluate demo lines asynchronously: each line runs in
233	        // its own `Timeout::new(0, ...)` tick so the browser can
234	        // paint the preceding line's output and process input
235	        // between lines. A long-running single line (e.g. `train
236	        // 30 { ... }`) still blocks the event loop *during* its
237	        // own eval -- fixing that needs Web Workers (see
238	        // docs/worker-threads.md) -- but the cross-line yield
239	        // keeps the tab from triggering the "unresponsive"
240	        // dialog on multi-line demos where the total wall clock
241	        // is the problem.
242	        //
243	        // We thread the accumulated `entries` vec through
244	        // recursion explicitly rather than reading from the
245	        // `UseStateHandle` inside each tick: a state handle is
246	        // snapshotted at the callback's closure-creation time
247	        // and does not refresh between `set()` calls, so reading
248	        // via `(*history).clone()` inside a deferred Timeout
249	        // reliably sees the stale initial value and each tick
250	        // overwrites the previous one's write. Passing `entries`
251	        // by move keeps a single authoritative Rust-side source
252	        // of truth; `history.set(entries.clone())` is purely for
253	        // the UI paint.
254	        schedule_demo_line(session.clone(), history.clone(), entries, demo, 0);
255	    })
256	}
