259	/// `:describe _demo` after a demo run reprints the intro +
260	/// takeaway. Uses MLPL's string-assignment syntax through `eval`
261	/// so the binding goes through the existing string-variable
262	/// surface (Saga 12 step 009) -- no new plumbing.
263	fn bind_demo_metadata(session: &WasmSession, demo: &crate::demos::Demo) {
264	    let body = format!(
