358	pub fn make_keydown(
359	    on_submit: Callback<String>,
360	    input_value: UseStateHandle<String>,
361	    cmd_history: UseStateHandle<Vec<String>>,
362	    cmd_index: UseStateHandle<Option<usize>>,
363	    completion_candidates: UseStateHandle<Vec<String>>,
364	    completion_selected: UseStateHandle<usize>,
365	) -> Callback<KeyboardEvent> {
366	    Callback::from(move |e: KeyboardEvent| {
367	        if crate::completion::is_completion_trigger(e.ctrl_key(), e.code().as_str()) {
368	            e.prevent_default();
369	            handle_completion(&e, &input_value, &completion_candidates, &completion_selected);
370	            return;
371	        }
372	        let popup_open = !completion_candidates.is_empty();
373	        if popup_open {
374	            if handle_popup_key(&e, &input_value, &completion_candidates, &completion_selected) {
375	                return;
376	            }
377	        }
378	        match e.key().as_str() {
379	            "Enter" => {
380	                e.prevent_default();
381	                on_submit.emit((*input_value).clone());
382	            }
383	            "ArrowUp" => {
384	                e.prevent_default();
385	                navigate_history_up(&input_value, &cmd_history, &cmd_index);
386	            }
387	            "ArrowDown" => {
388	                e.prevent_default();
389	                navigate_history_down(&input_value, &cmd_history, &cmd_index);
390	            }
391	            _ => {}
392	        }
393	    })
394	}
395	
396	fn navigate_history_up(
397	    input_value: &UseStateHandle<String>,
398	    cmd_history: &UseStateHandle<Vec<String>>,
399	    cmd_index: &UseStateHandle<Option<usize>>,
400	) {
401	    let cmds = &**cmd_history;
402	    if cmds.is_empty() {
403	        return;
404	    }
405	    let new_idx = match **cmd_index {
406	        None => cmds.len() - 1,
407	        Some(0) => 0,
408	        Some(i) => i - 1,
409	    };
410	    cmd_index.set(Some(new_idx));
411	    input_value.set(cmds[new_idx].clone());
412	}
413	
414	fn navigate_history_down(
415	    input_value: &UseStateHandle<String>,
416	    cmd_history: &UseStateHandle<Vec<String>>,
417	    cmd_index: &UseStateHandle<Option<usize>>,
418	) {
419	    let cmds = &**cmd_history;
420	    match **cmd_index {
421	        Some(i) if i + 1 < cmds.len() => {
422	            cmd_index.set(Some(i + 1));
423	            input_value.set(cmds[i + 1].clone());
424	        }
425	        Some(_) => {
426	            cmd_index.set(None);
427	            input_value.set(String::new());
428	        }
429	        None => {}
430	    }
431	}
432	
433	/// Handle keydown when the completion popup is open.
434	/// Returns true if the key was consumed (caller should return
435	/// early), false to fall through to normal handling.
436	fn handle_popup_key(
437	    e: &KeyboardEvent,
438	    input_value: &UseStateHandle<String>,
439	    candidates: &UseStateHandle<Vec<String>>,
440	    selected: &UseStateHandle<usize>,
441	) -> bool {
442	    let len = candidates.len();
443	    match e.key().as_str() {
444	        "ArrowDown" => {
445	            e.prevent_default();
446	            selected.set(crate::completion::next_index(**selected, len));
447	            true
448	        }
449	        "ArrowUp" => {
450	            e.prevent_default();
451	            selected.set(crate::completion::prev_index(**selected, len));
452	            true
453	        }
454	        "Enter" => {
455	            e.prevent_default();
456	            accept_selected(input_value, candidates, selected);
457	            true
458	        }
459	        "ArrowRight" => {
460	            let cursor = cursor_position(e);
461	            if crate::completion::should_accept_right(true, cursor, input_value.len()) {
462	                e.prevent_default();
463	                accept_selected(input_value, candidates, selected);
464	                true
465	            } else {
466	                false
467	            }
468	        }
469	        "Escape" => {
470	            e.prevent_default();
471	            candidates.set(Vec::new());
472	            selected.set(0);
473	            true
474	        }
475	        _ => false,
476	    }
477	}
478	
479	fn accept_selected(
480	    input_value: &UseStateHandle<String>,
481	    candidates: &UseStateHandle<Vec<String>>,
