pub fn make_keydown(
    on_submit: Callback<String>,
    input_value: UseStateHandle<String>,
    cmd_history: UseStateHandle<Vec<String>>,
    cmd_index: UseStateHandle<Option<usize>>,
    completion_candidates: UseStateHandle<Vec<String>>,
    completion_selected: UseStateHandle<usize>,
) -> Callback<KeyboardEvent> {
    Callback::from(move |e: KeyboardEvent| {
        if crate::completion::is_completion_trigger(e.ctrl_key(), e.code().as_str()) {
            e.prevent_default();
            handle_completion(&e, &input_value, &completion_candidates, &completion_selected);
            return;
        }
        let popup_open = !completion_candidates.is_empty();
        if popup_open {
            if handle_popup_key(&e, &input_value, &completion_candidates, &completion_selected) {
                return;
            }
        }
        match e.key().as_str() {
            "Enter" => {
                e.prevent_default();
                on_submit.emit((*input_value).clone());
            }
            "ArrowUp" => {
                e.prevent_default();
                navigate_history_up(&input_value, &cmd_history, &cmd_index);
            }
            "ArrowDown" => {
                e.prevent_default();
                navigate_history_down(&input_value, &cmd_history, &cmd_index);
            }
            _ => {}
        }
    })
}

fn navigate_history_up(
    input_value: &UseStateHandle<String>,
    cmd_history: &UseStateHandle<Vec<String>>,
    cmd_index: &UseStateHandle<Option<usize>>,
) {
    let cmds = &**cmd_history;
    if cmds.is_empty() {
        return;
    }
    let new_idx = match **cmd_index {
        None => cmds.len() - 1,
        Some(0) => 0,
        Some(i) => i - 1,
    };
    cmd_index.set(Some(new_idx));
    input_value.set(cmds[new_idx].clone());
}

fn navigate_history_down(
    input_value: &UseStateHandle<String>,
    cmd_history: &UseStateHandle<Vec<String>>,
    cmd_index: &UseStateHandle<Option<usize>>,
) {
    let cmds = &**cmd_history;
    match **cmd_index {
        Some(i) if i + 1 < cmds.len() => {
            cmd_index.set(Some(i + 1));
            input_value.set(cmds[i + 1].clone());
        }
        Some(_) => {
            cmd_index.set(None);
            input_value.set(String::new());
        }
        None => {}
    }
}

/// Handle keydown when the completion popup is open.
/// Returns true if the key was consumed (caller should return
/// early), false to fall through to normal handling.
fn handle_popup_key(
    e: &KeyboardEvent,
    input_value: &UseStateHandle<String>,
    candidates: &UseStateHandle<Vec<String>>,
    selected: &UseStateHandle<usize>,
) -> bool {
    let len = candidates.len();
    match e.key().as_str() {
        "ArrowDown" => {
            e.prevent_default();
            selected.set(crate::completion::next_index(**selected, len));
            true
        }
        "ArrowUp" => {
            e.prevent_default();
            selected.set(crate::completion::prev_index(**selected, len));
            true
        }
        "Enter" => {
            e.prevent_default();
            accept_selected(input_value, candidates, selected);
            true
        }
        "ArrowRight" => {
            let cursor = cursor_position(e);
            if crate::completion::should_accept_right(true, cursor, input_value.len()) {
                e.prevent_default();
                accept_selected(input_value, candidates, selected);
                true
            } else {
                false
            }
        }
        "Escape" => {
            e.prevent_default();
            candidates.set(Vec::new());
            selected.set(0);
            true
        }
        _ => false,
    }
}

fn accept_selected(
    input_value: &UseStateHandle<String>,
    candidates: &UseStateHandle<Vec<String>>,
    selected: &UseStateHandle<usize>,
) {
    let idx = (**selected).min(candidates.len().saturating_sub(1));
    if let Some(chosen) = candidates.get(idx) {
        let cur = input_value.len();
        let (out, _) = crate::completion::apply_completion(&input_value, cur, chosen);
        input_value.set(out);
    }
    candidates.set(Vec::new());
    selected.set(0);
}

fn cursor_position(e: &KeyboardEvent) -> usize {
    e.target()
        .and_then(|t| t.dyn_into::<HtmlInputElement>().ok())
        .and_then(|el| el.selection_start().ok().flatten())
        .map(|p| p as usize)
        .unwrap_or(0)
}

/// Saga 33 step 045 (was step 043's `handle_tab`):
/// completion keydown handler. Reads cursor pos from the
/// underlying HtmlInputElement, runs the candidate pipeline,
/// and either inserts a unique completion in-place or pops
/// up the multi-match list.
fn handle_completion(
    e: &KeyboardEvent,
    input_value: &UseStateHandle<String>,
    completion_candidates: &UseStateHandle<Vec<String>>,
    completion_selected: &UseStateHandle<usize>,
) {
    let cursor = e
        .target()
        .and_then(|t| t.dyn_into::<HtmlInputElement>().ok())
        .and_then(|el| el.selection_start().ok().flatten())
        .map(|p| p as usize)
        .unwrap_or_else(|| input_value.len());
    let value = (**input_value).clone();
    // mlpl-eval is wasm-only in this crate (see Cargo.toml).
    // On native (tests), the builtin list collapses to empty
    // -- pure helpers are covered by completion::tests.
    #[cfg(target_arch = "wasm32")]
    let builtins: Vec<&str> = mlpl_eval::runtime_builtin_names().collect();
    #[cfg(not(target_arch = "wasm32"))]
    let builtins: Vec<&str> = Vec::new();
    match crate::completion::compute_tab_match(&value, cursor, builtins.iter().copied()) {
        crate::completion::TabMatch::None => {
            completion_candidates.set(Vec::new());
            completion_selected.set(0);
        }
        crate::completion::TabMatch::Apply { input, cursor: _ } => {
            input_value.set(input);
            completion_candidates.set(Vec::new());
            completion_selected.set(0);
        }
        crate::completion::TabMatch::Popup(v) => {
            completion_candidates.set(v);
            completion_selected.set(0);
        }
    }
}

