1	//! Saga 33 step 043 + 045: REPL completion popup. Pure
2	//! helpers -- prefix extraction, candidate matching,
3	//! completion application, the trigger-key predicate --
4	//! plus the static candidate list (REPL commands + language
5	//! keywords). Builtin names are sourced from
6	//! `mlpl_runtime::runtime_builtin_names()` at call sites
7	//! since they live in a different crate.
8	//!
9	//! Trigger: **Ctrl+Space** (IDE standard -- VS Code,
10	//! IntelliJ, Emacs). Tab was the original step-043 trigger
11	//! but the browser's focus-traversal default beat
12	//! `preventDefault`; Tab is now reserved for browser
13	//! element navigation and Ctrl+Space takes over.
14	//!
15	//! Tests live in this same file: the helpers are pure and
16	//! need no Yew runtime.
17	
18	/// Characters that count as part of a completable token.
19	/// Alphanumeric + underscore + leading colon (for `:cmds`).
20	fn is_token_char(c: char) -> bool {
21	    c.is_alphanumeric() || c == '_' || c == ':'
22	}
23	
24	/// Find the token prefix ending at `cursor` in `input`.
25	/// Returns `(prefix_start, prefix)` -- empty `prefix` means
26	/// the cursor is on whitespace and there's nothing to
27	/// complete. `cursor` is clamped to `input.len()`.
28	pub fn extract_prefix(input: &str, cursor: usize) -> (usize, &str) {
29	    let cursor = cursor.min(input.len());
30	    // Walk backward from cursor while chars are token-y.
31	    let mut start = cursor;
32	    for (i, c) in input[..cursor].char_indices().rev() {
33	        if is_token_char(c) {
34	            start = i;
35	        } else {
36	            break;
37	        }
38	    }
39	    (start, &input[start..cursor])
40	}
41	
42	/// Filter `candidates` to those starting with `prefix`.
43	/// Returns an owned sorted-deduped Vec to keep callers
44	/// simple. Empty prefix returns empty (nothing to complete).
45	pub fn match_candidates(prefix: &str, candidates: &[&str]) -> Vec<String> {
46	    if prefix.is_empty() {
47	        return Vec::new();
48	    }
49	    let mut out: Vec<String> = candidates
50	        .iter()
51	        .filter(|c| c.starts_with(prefix) && **c != prefix)
52	        .map(|c| (*c).to_string())
53	        .collect();
54	    out.sort();
55	    out.dedup();
56	    out
57	}
58	
59	/// Apply `completion` at `cursor` in `input`, replacing the
60	/// token prefix at the cursor. Returns `(new_input,
61	/// new_cursor)` where the cursor lands at the end of the
62	/// inserted completion.
63	pub fn apply_completion(input: &str, cursor: usize, completion: &str) -> (String, usize) {
64	    let (start, _prefix) = extract_prefix(input, cursor);
65	    let cursor = cursor.min(input.len());
66	    let mut out = String::with_capacity(input.len() + completion.len());
67	    out.push_str(&input[..start]);
68	    out.push_str(completion);
69	    out.push_str(&input[cursor..]);
70	    let new_cursor = start + completion.len();
71	    (out, new_cursor)
72	}
73	
74	/// Static REPL command names recognized by mlpl-eval's
75	/// inspect dispatcher (mirrors `inspect.rs::topic_output`
76	/// plus the arg-taking arms). Stays in sync manually.
77	pub const REPL_COMMANDS: &[&str] = &[
78	    ":builtins",
79	    ":describe",
80	    ":experiments",
81	    ":fns",
82	    ":help",
83	    ":introspect",
84	    ":models",
85	    ":tags",
86	    ":untag",
87	    ":upload",
88	    ":vars",
89	    ":version",
90	    ":wsid",
91	];
92	
93	/// Static MLPL language keywords. Small enough to enumerate;
94	/// stays in sync with parser literals.
95	pub const KEYWORDS: &[&str] = &["train", "repeat", "experiment", "for", "in", "param"];
96	
97	/// Wrap-around index increment for popup navigation.
98	pub fn next_index(cur: usize, len: usize) -> usize {
99	    if len == 0 {
100	        return 0;
101	    }
102	    (cur + 1) % len
103	}
104	
105	/// Wrap-around index decrement for popup navigation.
106	pub fn prev_index(cur: usize, len: usize) -> usize {
107	    if len == 0 {
108	        return 0;
109	    }
110	    if cur == 0 { len - 1 } else { cur - 1 }
111	}
112	
113	/// ArrowRight should accept the highlighted candidate only
114	/// when the popup is open AND the cursor is at the end of
115	/// the input (otherwise ArrowRight is a normal cursor move).
116	pub fn should_accept_right(popup_open: bool, cursor: usize, input_len: usize) -> bool {
117	    popup_open && cursor >= input_len
